psql -v ON_ERROR_STOP=1 -f etl.sql; echo "EXIT=$?"
psql <<'EOF'
SELECT * FROM etl_run_log ORDER BY run_id;
SELECT * FROM dash_revenue_by_category WHERE month='2026-10' ORDER BY category;
SELECT * FROM dash_revenue_by_country WHERE month='2026-10' ORDER BY country;
SELECT 'naive line-level rollup would give' AS info,
       (SELECT SUM(order_count) FROM (
          SELECT to_char(o.order_date,'YYYY-MM') m, p.category, count(DISTINCT o.order_id) order_count
          FROM orders o JOIN order_items oi ON oi.order_id=o.order_id
          JOIN products p ON p.product_id=oi.product_id
          WHERE o.status='COMPLETED' GROUP BY 1,2) t) AS naive_loaded;
EOF

