input.command:
cat > /tmp/opencode/gate_test.sql <<'EOF'
BEGIN;
INSERT INTO etl_run_log (started_at, finished_at, source_order_count, loaded_order_count, mismatch)
VALUES (clock_timestamp(), clock_timestamp(), 100, 99, 1);
DO $$
DECLARE
    v_run_id   bigint;
    v_mismatch bigint;
BEGIN
    SELECT run_id, mismatch INTO v_run_id, v_mismatch
    FROM etl_run_log ORDER BY run_id DESC LIMIT 1;
    IF v_mismatch IS NULL OR v_mismatch <> 0 THEN
        RAISE EXCEPTION 'ETL reconciliation FAILED (etl_run_log run %): source_order_count - loaded_order_count = % (must be 0)', v_run_id, v_mismatch;
    END IF;
END
$$;
ROLLBACK;
EOF
psql -v ON_ERROR_STOP=1 -f /tmp/opencode/gate_test.sql; echo "GATE_TEST_EXIT=$?"
psql -At -c "select count(*) from etl_run_log;"

